<?php
namespace App\Services;
use App\Models\{DeliveryAttempt,DeliveryProof,Parcel,PickupAssignment,RiderEarning,ShipmentEvent,User};
use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class RiderFulfillmentService {
 public function confirmPickup(PickupAssignment $assignment,User $rider):void{DB::transaction(function()use($assignment,$rider){$assignment=PickupAssignment::with('request.parcels.shipment')->lockForUpdate()->findOrFail($assignment->id);if($assignment->riderProfile->user_id!==$rider->id)throw ValidationException::withMessages(['pickup'=>'This pickup is assigned to another rider.']);$assignment->update(['status'=>'completed','picked_up_at'=>$assignment->picked_up_at??now(),'completed_at'=>now()]);foreach($assignment->request->parcels as $parcel){$old=$parcel->status;$parcel->update(['status'=>'picked_up','last_event_at'=>now()]);$parcel->shipment->update(['status'=>'in_transit']);ShipmentEvent::create(['shipment_id'=>$parcel->shipment_id,'parcel_id'=>$parcel->id,'event_type'=>'rider_pickup','from_status'=>$old,'to_status'=>'picked_up','actor_user_id'=>$rider->id,'source'=>'rider','occurred_at'=>now()]);}RiderEarning::firstOrCreate(['rider_profile_id'=>$assignment->rider_profile_id,'pickup_assignment_id'=>$assignment->id,'type'=>'pickup'],['amount_minor'=>5000,'status'=>'posted','description'=>'Completed pickup '.$assignment->request->pickup_no,'earned_at'=>now(),'posted_at'=>now()]);},3);}
 public function recordDelivery(Parcel $parcel,User $rider,array $data,?UploadedFile $proof):DeliveryAttempt{return DB::transaction(function()use($parcel,$rider,$data,$proof){$profile=$rider->riderProfile;if(!$profile)throw ValidationException::withMessages(['delivery'=>'Rider profile unavailable.']);$attemptNo=DeliveryAttempt::where('parcel_id',$parcel->id)->lockForUpdate()->max('attempt_no')+1;$attempt=DeliveryAttempt::create(['parcel_id'=>$parcel->id,'rider_profile_id'=>$profile->id,'attempt_no'=>$attemptNo,'outcome'=>$data['outcome'],'failure_reason'=>$data['failure_reason']??null,'notes'=>$data['notes']??null,'attempted_at'=>now()]);if($data['outcome']==='delivered'){DeliveryProof::create(['delivery_attempt_id'=>$attempt->id,'type'=>$proof?'photo':'recipient','file_path'=>$proof?->store('delivery-proofs','public'),'recipient_name'=>$data['recipient_name']??null,'captured_at'=>now(),'uploaded_by'=>$rider->id]);}$old=$parcel->status;$status=$data['outcome']==='delivered'?'delivered':'delivery_failed';$parcel->update(['status'=>$status,'last_event_at'=>now()]);$parcel->shipment->update(['status'=>$status,'delivered_at'=>$status==='delivered'?now():null]);ShipmentEvent::create(['shipment_id'=>$parcel->shipment_id,'parcel_id'=>$parcel->id,'event_type'=>'delivery_attempt','from_status'=>$old,'to_status'=>$status,'actor_user_id'=>$rider->id,'source'=>'rider','notes'=>$data['notes']??null,'occurred_at'=>now()]);if($status==='delivered')RiderEarning::firstOrCreate(['rider_profile_id'=>$profile->id,'delivery_attempt_id'=>$attempt->id,'type'=>'delivery'],['amount_minor'=>7000,'status'=>'posted','description'=>'Delivered parcel '.$parcel->parcel_no,'earned_at'=>now(),'posted_at'=>now()]);return $attempt;},3);}
}
